            margin-bottom: 4rem;
        }

        .book-card {
            background: var(--card-bg);
            border: 1px solid #eee;
            border-radius: 8px;
            overflow: hidden;
            transition: transform 0.2s, box-shadow 0.2s;
            display: flex;
            flex-direction: column;
        }

        .book-card:hover {
