            margin-bottom: 1rem;
        }

        .review-snippet {
            font-size: 0.95rem;
            color: #444;
            margin-bottom: 1rem;
            flex-grow: 1;
        }

        .read-more {
            text-decoration: none;
            color: var(--accent-color);
            font-weight: bold;
            font-family: sans-serif;
            font-size: 0.9rem;
            align-self: flex-start;
        }

        /* --- Newsletter --- */
        .newsletter {
            background-color: var(--primary-color);
            color: white;
            text-align: center;
            padding: 3rem 1rem;
