            background-color: var(--accent-color);
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: bold;
        }

        /* --- Footer --- */
        footer {
            background-color: #222;
            color: #888;
            text-align: center;
            padding: 2rem;
            font-family: sans-serif;
            font-size: 0.8rem;
        }

        /* --- Responsive Tweaks --- */
        @media (max-width: 768px) {
            .hero {
                flex-direction: column;
                text-align: center;
            }

            .hero-image {
                max-width: 200px;
            }

            .newsletter input[type="email"] {
                width: 100%;
                margin-bottom: 10px;
            }
        }
    </style>
